<?php
namespace App\Http\Controllers\UserArea; use App\Http\Controllers\Controller; use App\Models\StayLifecycleEvent; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class StayLifecycleController extends Controller {public function checkIn(Request $r,string $reference){$b=$r->user()->bookings()->with(['guests.identityDocument','guests.identityLink'])->where('reference',$reference)->first();abort_unless($b,403);if(!$b->isCheckInEligible())return back()->with('error','This booking is not currently eligible for check-in.');try{DB::transaction(function()use($r,$b){$b->update(['checked_in_at'=>now(),'status'=>'checked_in']);StayLifecycleEvent::create(['booking_id'=>$b->id,'actor_id'=>$r->user()->id,'event'=>'checked_in','viewer_timezone'=>$r->user()->timezone,'operational_timezone'=>config('azari.timezone','Africa/Lagos'),'ip_address'=>$r->ip(),'user_agent'=>substr((string)$r->userAgent(),0,1000)]);});return back()->with('success','Check-in completed.');}catch(\Throwable $e){report($e);return back()->with('error','Check-in could not be completed. Please try again.');}}}
